-- Public marketing sites for the sites app. Visitors read with the anon key. Writes stay in SQL.

create table public.site (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  custom_domain text unique,
  status text not null default 'demo',
  preset text not null,
  document jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint site_slug_format check (slug ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'),
  constraint site_status_check check (status in ('demo', 'live')),
  constraint site_preset_check check (preset in (
    'clean-studio',
    'soft-luxury',
    'portfolio-first',
    'home-studio',
    'bold-nail-bar',
    'clinic-professional',
    'hair-beauty-menu',
    'review-led',
    'courses-treatments',
    'neighbourhood-salon'
  )),
  constraint site_custom_domain_host check (
    custom_domain is null
    or (
      custom_domain = lower(custom_domain)
      and position(' ' in custom_domain) = 0
      and custom_domain !~* '\.simpleoutcome\.dev$'
      and custom_domain <> 'simpleoutcome.dev'
    )
  ),
  constraint site_document_object check (
    jsonb_typeof(document) = 'object'
    and document->>'schemaVersion' = '1'
  )
);

create trigger site_set_updated_at
  before update on public.site
  for each row execute function extensions.moddatetime('updated_at');

alter table public.site enable row level security;

create policy site_select_public on public.site
  for select to anon, authenticated
  using (true);

grant select on public.site to anon, authenticated;
revoke insert, update, delete on public.site from anon, authenticated;

